                url_str = img_data.get("image_url", {})
                if isinstance(url_str, dict):
                    url_str = url_str.get("url", "")
                else:
                    url_str = str(url_str)
            else:
                url_str = str(img_data)

            if url_str.startswith("data:image/png;base64,"):
                b64 = url_str.split(",", 1)[1]
                img_bytes = base64.b64decode(b64)
            elif url_str.startswith("http"):
                img_bytes = requests.get(url_str, timeout=60).content
            else:
                print(f"  Unexpected format")
                return None

            Path(output_path).parent.mkdir(parents=True, exist_ok=True)
            with open(output_path, "wb") as f:
                f.write(img_bytes)
            size_kb = len(img_bytes) / 1024
            print(f"  ✅ Saved: {output_path} ({size_kb:.0f} KB)")
            return str(output_path)

        except Exception as e:
            print(f"  Error: {e}, attempt {attempt+1}")
            if attempt < retries:
                time.sleep(5)
    return None


